import { tokenConfig } from '../../auth/tokenConfig';
import { all, call, fork, put, takeEvery } from 'redux-saga/effects';
import axios from 'axios';
import {
    updateManufacturerPriceDiscountSuccess,
    updateManufacturerPriceDiscountFailed,
    createManufacturerPriceDiscountFailed,
    createManufacturerPriceDiscountSuccess,
    getManufacturerPriceDiscountsSuccess,
    getManufacturerPriceDiscountsFailed,
    getManufacturerPriceDiscountByIdSuccess,
    getManufacturerPriceDiscountByIdFailed,
} from './actions';
import {
    CREATE_MANUFACTURER_PRICE_DISCOUNT,
    GET_MANUFACTURER_PRICE_DISCOUNTS,
    GET_MANUFACTURER_PRICE_DISCOUNT_BY_ID,
    UPDATE_MANUFACTURER_PRICE_DISCOUNT,
} from './constants';

function* getManufacturerPriceDiscounts() {
    const apiCall = () => {
        return axios
            .get('manufacturers/price-discounts', tokenConfig())
            .then((response) => response.data)
            .catch((err) => {
                throw err;
            });
    };

    try {
        const response = yield call(apiCall);

        yield put(getManufacturerPriceDiscountsSuccess(response));
    } catch (error) {
        let message;
        console.log('ERRORS', error.response);
        switch (error.status) {
            case 500:
                message = 'Internal Server Error';
                break;
            case 401:
                message = 'Invalid credentials';
                break;
            default:
                message = error;
        }
        yield put(getManufacturerPriceDiscountsFailed(message, error.response.data.errors));
    }
}

//Create wholesale price discount
function* createManufacturerPriceDiscount(payload) {
    console.log('Payload', payload);
    const apiCall = () => {
        return axios
            .post('manufacturers/price-discounts/create', payload.payload, tokenConfig())
            .then((response) => response.data)
            .catch((err) => {
                throw err;
            });
    };

    try {
        const response = yield call(apiCall);
        yield put(createManufacturerPriceDiscountSuccess(response));
    } catch (error) {
        let message;

        console.log('ERRORS', error.response.data);
        switch (error.status) {
            case 500:
                message = 'Internal Server Error';
                break;
            case 401:
                message = 'Invalid credentials';
                break;
            default:
                message = error;
        }
        yield put(createManufacturerPriceDiscountFailed(message, error.response.data.errors));
    }
}

//Update wholesale variation receipt
function* updateManufacturerPriceDiscount(payload) {
    const apiCall = () => {
        return axios
            .patch(`manufacturers/price-discounts/${payload.payload.id}/update`, payload.payload.data, tokenConfig())
            .then((response) => response.data)
            .catch((err) => {
                throw err;
            });
    };

    try {
        const response = yield call(apiCall);

        yield put(updateManufacturerPriceDiscountSuccess(response));
    } catch (error) {
        let message;

        console.log('ERRORS', error.response.data);
        switch (error.status) {
            case 500:
                message = 'Internal Server Error';
                break;
            case 401:
                message = 'Invalid credentials';
                break;
            default:
                message = error.response.data.detail;
        }
        yield put(updateManufacturerPriceDiscountFailed(message, error.response.data.errors));
    }
}

//Get wholesaler price discount by ID
function* getManufacturerPriceDiscountById(payload) {
    const apiCall = () => {
        return axios
            .get(`manufacturers/price-discounts/${payload.payload}`, tokenConfig())
            .then((response) => response.data)
            .catch((err) => {
                throw err;
            });
    };

    try {
        const response = yield call(apiCall);

        yield put(getManufacturerPriceDiscountByIdSuccess(response));
    } catch (error) {
        let message;
        switch (error.status) {
            case 500:
                message = 'Internal Server Error';
                break;
            case 401:
                message = 'Invalid credentials';
                break;
            default:
                message = error;
        }
        yield put(getManufacturerPriceDiscountByIdFailed(message, error.response.data.errors));
    }
}

//Get wholesaler price discounts
//Get variations
export function* watchGetManufacturerPriceDiscounts() {
    yield takeEvery(GET_MANUFACTURER_PRICE_DISCOUNTS, getManufacturerPriceDiscounts);
}

//PRICE_DISCOUNTS
//Create wholesale receipt
export function* watchCreateManufacturerPriceDiscount() {
    yield takeEvery(CREATE_MANUFACTURER_PRICE_DISCOUNT, createManufacturerPriceDiscount);
}
//Update wholesale receipt
export function* watchUpdateManufacturerPriceDiscount() {
    yield takeEvery(UPDATE_MANUFACTURER_PRICE_DISCOUNT, updateManufacturerPriceDiscount);
}

//Update wholesale receipt
export function* watchGetManufacturerPriceDiscountyById() {
    yield takeEvery(GET_MANUFACTURER_PRICE_DISCOUNT_BY_ID, getManufacturerPriceDiscountById);
}
function* manufacturerPriceDiscountsSaga() {
    yield all([
        fork(watchCreateManufacturerPriceDiscount),
        fork(watchGetManufacturerPriceDiscounts),
        fork(watchUpdateManufacturerPriceDiscount),
        fork(watchGetManufacturerPriceDiscountyById),
    ]);
}

export default manufacturerPriceDiscountsSaga;
